/* ===== البذور الخمس والأخلاق ===== */
const IMG={home:"data:image/jpeg;base64,",plant:"data:image/jpeg;base64,",pots:"data:image/jpeg;base64,",water:"data:image/jpeg;base64,",queue:"data:image/jpeg;base64,",toys:"data:image/jpeg;base64,",shop:"data:image/jpeg;base64,",three:"data:image/jpeg;base64,",boys:"data:image/jpeg;base64,",stages:"data:image/jpeg;base64,",broken:"data:image/jpeg;base64,"};
const AR='٠١٢٣٤٥٦٧٨٩',toAr=n=>String(n).replace(/\d/g,d=>AR[d]);

/* ================= drawn illustrations (same flat style everywhere) ================= */
function heart(x,y,r,c,o=1){return `<path d="M${x} ${y+r*.9} C${x-r*1.7} ${y-r*.15} ${x-r*.75} ${y-r*1.35} ${x} ${y-r*.45} C${x+r*.75} ${y-r*1.35} ${x+r*1.7} ${y-r*.15} ${x} ${y+r*.9}Z" fill="${c}" opacity="${o}"/>`}
function star(x,y,r,c='#F2C14E',o=1){let d='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.46:r;d+=(i?'L':'M')+(x+rr*Math.cos(a)).toFixed(1)+' '+(y+rr*Math.sin(a)).toFixed(1)}return `<path d="${d}Z" fill="${c}" opacity="${o}" stroke="${c}" stroke-width="1.5" stroke-linejoin="round"/>`}
const leafS=(x,y,a,s=1,c='#5DAA68')=>`<ellipse cx="${x}" cy="${y}" rx="${9*s}" ry="${4.5*s}" fill="${c}" transform="rotate(${a} ${x} ${y})"/>`;
function plant(stage,fc='#F2C14E'){ // drawn above soil line y=-52
 if(stage<=0)return '';
 const h=[0,14,30,50,72][stage];let g=`<path d="M0 -52 V${-52-h}" stroke="#4E9F5A" stroke-width="${2+stage*.6}" stroke-linecap="round"/>`;
 g+=leafS(-7,-52-h*.55,-30,.7+stage*.15)+leafS(7,-52-h*.6,30,.7+stage*.15);
 if(stage>=3)g+=leafS(-8,-52-h*.85,-40,.9)+leafS(8,-52-h*.88,40,.9);
 if(stage>=4){for(let i=0;i<5;i++){const a=i*1.2566-1.57;g+=`<circle cx="${(9*Math.cos(a)).toFixed(1)}" cy="${(-52-h-4+9*Math.sin(a)).toFixed(1)}" r="6.5" fill="${fc}"/>`}g+=`<circle cx="0" cy="${-52-h-4}" r="4.5" fill="#B5512A"/>`}
 return g;
}
function pot(x,y,s=1,stage=0,fc){return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="0" cy="2" rx="34" ry="5" fill="#3A2A12" opacity=".15"/>${plant(stage,fc)}<path d="M-30 -50 H30 L22 0 H-22Z" fill="url(#gPot)"/><rect x="-35" y="-58" width="70" height="12" rx="4" fill="#DE8457"/><ellipse cx="0" cy="-52" rx="27" ry="4" fill="#6B4A2F"/></g>`}
const seed=(x,y,r=0,s=1)=>`<g transform="translate(${x} ${y}) rotate(${r}) scale(${s})"><ellipse rx="7" ry="4.6" fill="#8B5E34"/><ellipse cx="-2" cy="-1.5" rx="2.6" ry="1.2" fill="#C49567"/></g>`;
const coin=(x,y,r=11)=>`<g><circle cx="${x}" cy="${y}" r="${r}" fill="#F2C14E" stroke="#D29B1E" stroke-width="2.5"/><circle cx="${x}" cy="${y}" r="${r*.6}" fill="none" stroke="#D29B1E" stroke-width="1.6"/></g>`;
const sun=(x,y,r=26)=>`<circle cx="${x}" cy="${y}" r="${r*2.2}" fill="url(#gGlow)"/><circle cx="${x}" cy="${y}" r="${r}" fill="#FFD45C"/>`;
const cloud=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})" fill="#fff" opacity=".95"><ellipse rx="38" ry="15"/><ellipse cx="-22" cy="5" rx="22" ry="12"/><ellipse cx="24" cy="5" rx="24" ry="12"/><ellipse cx="2" cy="-11" rx="22" ry="15"/></g>`;
const grass=(y=232)=>`<path d="M0 ${y} Q200 ${y-24} 400 ${y} V320 H0Z" fill="url(#gGrass)"/>`;
const sparkle=l=>l.map(([x,y,r,c])=>star(x,y,r,c||'#F2C14E',.9)).join('');
const can=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-26 -44 H22 L18 0 H-22Z" fill="#4A93C9"/><path d="M22 -36 L58 -62" stroke="#4A93C9" stroke-width="8" stroke-linecap="round"/><ellipse cx="60" cy="-64" rx="8" ry="5" fill="#3A7DB0" transform="rotate(-35 60 -64)"/><path d="M-26 -36 Q-46 -24 -26 -8" stroke="#3A7DB0" stroke-width="6" fill="none"/><rect x="-26" y="-48" width="48" height="8" rx="3" fill="#3A7DB0"/></g>`;
const ball=(x,y,r=16)=>`<g><circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#3A3A3A" stroke-width="2"/><path d="M${x} ${y-r*.45} l${r*.43} ${r*.31} l${-r*.16} ${r*.5} h${-r*.54} l${-r*.16} ${-r*.5}Z" fill="#3A3A3A"/></g>`;
const bag=(x,y,s=1,c='#4A93C9',c2='#F2C14E')=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-16 -74 Q0 -96 16 -74" stroke="${c}" stroke-width="7" fill="none" stroke-linecap="round"/><rect x="-32" y="-76" width="64" height="76" rx="16" fill="${c}"/><rect x="-22" y="-38" width="44" height="28" rx="8" fill="${c2}"/></g>`;
const house=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-60" y="-70" width="120" height="70" rx="4" fill="#FFF3DC"/><path d="M-72 -66 L0 -118 L72 -66Z" fill="#C8673E"/><rect x="-14" y="-40" width="28" height="40" rx="12" fill="#9C6B3F"/><rect x="-46" y="-52" width="22" height="20" rx="3" fill="#A6DCF2" stroke="#fff" stroke-width="3"/><rect x="24" y="-52" width="22" height="20" rx="3" fill="#A6DCF2" stroke="#fff" stroke-width="3"/></g>`;
const tree=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-7" y="-60" width="14" height="60" rx="5" fill="#9C6B3F"/><circle cy="-84" r="34" fill="#5DAA68"/><circle cx="-24" cy="-68" r="22" fill="#4E9F5A"/><circle cx="24" cy="-66" r="24" fill="#4E9F5A"/><circle cx="8" cy="-100" r="20" fill="#7CC27A"/></g>`;
const fiveRow=(y,s,st,fcs=['#F2C14E','#E8786A','#F2C14E','#E8786A','#F2C14E'])=>[60,130,200,270,340].map((x,i)=>pot(x,y,s,Array.isArray(st)?st[i]:st,fcs[i])).join('');
const SV=(bg,c)=>`<svg viewBox="0 0 400 320" preserveAspectRatio="xMidYMid slice"><rect width="400" height="320" fill="${bg}"/>${c}</svg>`;
const garden=(c,eve)=>SV(eve?'url(#gEve)':'url(#gSky)',(eve?sun(320,90,24):sun(330,62,22)+cloud(110,58,.9))+grass()+c);

