 sprout:garden(`<ellipse cx="200" cy="262" rx="90" ry="18" fill="#7A5434"/>`+`<g transform="translate(200 314) scale(2.2)">${plant(2)}</g>`+seed(150,262,20,1.4)+seed(250,266,-15,1.4)+sparkle([[200,120,9],[120,150,6],[280,150,6]])),
