const COVER={hard:1,html:`<div class="cv"><div class="cv-t">البذور الخمس<br>والأخلاق</div><div class="cv-p">${ART.cover}</div><button type="button" class="cv-b" data-start>هيا نقرأ القصة</button></div>`};
const BACK={hard:1,html:`<div class="cv"><div class="cv-p">${ART.glow}</div><div class="cv-t" style="font-size:7cqw">فأي بذرة ستزرع اليوم؟ 🌱</div><div class="cv-s">البذور الخمس والأخلاق</div></div>`};
const R=[COVER,...STORY,BACK],N=R.length;
if(N%2)console.warn('odd page count');

/* ================= quiz ================= */
const QUIZ=[
 {q:'ماذا فعل الجد عندما اكتشف أن البائع أعطاه مالًا زائدًا؟',o:['احتفظ بالمال.','أعاد المال إلى صاحبه.','اشترى به لعبة.'],a:1},
 {q:'ماذا فعل آدم عندما انكسر الأصيص؟',o:['ألقى اللوم على الرياح.','أخفى الحقيقة.','اعترف بما حدث.'],a:2},
 {q:`ماذا نتعلم من الآية ${VERSE}؟`,o:['أن حسن الخلق أمر عظيم.','أن النباتات لا تحتاج إلى الماء.','أن المشاركة أمر غير مهم.'],a:0},
 {q:'كيف ننمّي أخلاقنا؟',o:['بالمواقف الصحيحة كل يوم.','بالكلام فقط.','بتجاهل الآخرين.'],a:0}
];
let qi=0;const PRAISE=['أحسنت!','رائع، لقد تذكرت الدرس!'];
function renderQuiz(){
 const box=document.getElementById('quiz');if(!box)return;
 if(qi>=QUIZ.length){box.innerHTML=`<div class="qq" style="text-align:center">رائع، لقد تذكرت الدرس! 🌱</div><div style="text-align:center"><button type="button" class="qbtn alt" data-qreset>إعادة المحاولة</button></div>`;return}
 const Q=QUIZ[qi];
 box.innerHTML=`<div class="qn">السؤال ${toAr(qi+1)} من ${toAr(QUIZ.length)}</div><div class="qq">${Q.q}</div><div class="opts">${Q.o.map((o,i)=>`<button type="button" class="opt" data-opt="${i}">${o}</button>`).join('')}</div><div class="fb" aria-live="polite"></div>`;
}
function onQuiz(e){
 const o=e.target.closest('[data-opt]'),r=e.target.closest('[data-qreset]'),n=e.target.closest('[data-qnext]');
 if(r){qi=0;renderQuiz();return true}
 if(n){qi++;renderQuiz();return true}
 if(!o)return false;
 const Q=QUIZ[qi],i=+o.dataset.opt,fb=o.closest('#quiz').querySelector('.fb');
 if(i===Q.a){o.classList.add('ok');o.parentNode.querySelectorAll('.opt').forEach(b=>b.disabled=true);
  fb.className='fb';fb.innerHTML=`${PRAISE[qi%2]} <button type="button" class="qbtn" data-qnext>${qi<QUIZ.length-1?'السؤال التالي':'إنهاء'}</button>`}
 else{o.classList.add('no');fb.className='fb try';fb.textContent='حاول مرة أخرى.'}
 return true;
}

/* ================= build pages ================= */
const LEAF=`<svg class="leaf" viewBox="0 0 40 40"><path d="M6 36 Q8 10 34 6 Q32 30 6 36Z" fill="#7CC27A"/><path d="M6 36 Q18 22 30 10" stroke="#4E9F5A" stroke-width="2" fill="none"/></svg>`;
const SINGLE=false;   // always two pages side by side, like an open book
/* Two ways of turning pages (button «اتجاه التقليب»):
   'ar' (default) — a real Arabic book: bound on the right, it opens from the right side,
        each page is lifted from the left edge and laid over to the right, read pages pile up on the right.
   'en' — the page lifts from the right edge and lands on the left (right page is still read first). */
const DIR='ar';try{localStorage.removeItem('flipdir')}catch(_){} // always a real Arabic book
const AR_=DIR==='ar';
const libToRead=L=>{if(AR_)return N-1-L;if(SINGLE||L===0||L===N-1)return L;return L%2?L+1:L-1};
const readToLib=r=>{if(AR_)return N-1-r;if(SINGLE||r===0||r===N-1)return r;return r%2?r+1:r-1};
function pageEl(pg,r){
 const L=readToLib(r),el=document.createElement('div');
 el.className='page '+(SINGLE?'pr':(L%2?'pl':'pr'))+(pg.hard?' hard':'');
 if(pg.hard){el.dataset.density='hard';el.innerHTML=pg.html;return el}
 el.innerHTML=`<div class="pg"><div class="ill">${pg.img.h}${pg.tag?`<div class="tag">${pg.tag}</div>`:''}</div><div class="txt${pg.c?' c':''}${pg.quiz?' quiz':''}"><div class="in">${pg.txt}</div>${pg.quiz?'':LEAF}</div></div><div class="num">${toAr(r)}</div>`;
 if(pg.quiz)el.dataset.nofit=1;
 return el;
}
const els=R.map(pageEl);           // reading order
function fitText(){ // keep every passage fully visible; shrink only slightly if needed
 const m=document.getElementById('measure');
 els.forEach((el,i)=>{const t=el.querySelector('.txt');if(!t||el.dataset.nofit)return;
  m.appendChild(el);let s=4.4;t.style.fontSize=s+'cqw';const inn=t.querySelector('.in');
  while(s>3.8&&inn.scrollHeight>t.clientHeight-4){s-=.1;t.style.fontSize=s.toFixed(2)+'cqw'}
  if(inn.scrollHeight>t.clientHeight-4)console.warn('text too long on page',i);
  m.removeChild(el)});
}

/* ================= book ================= */
const stage=document.getElementById('stage'),bookEl=document.getElementById('book');
function fit(){let h=innerHeight-(innerHeight<500?78:innerWidth<600?150:120),w=h*550/720;const maxW=innerWidth*.96/2;if(w>maxW)w=maxW;stage.style.width=Math.floor(w*2)+'px'}
fit();
addEventListener('resize',fit);

let pf,state='read';
/* soft paper rustle made with the Web Audio API (no sound file needed) */
let actx,soundOn=true;
function rustle(){
 if(!soundOn)return;
 try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();
  const dur=.5,sr=actx.sampleRate,buf=actx.createBuffer(1,sr*dur,sr),ch=buf.getChannelData(0);
  for(let i=0;i<ch.length;i++){const t=i/ch.length;ch[i]=(Math.random()*2-1)*Math.sin(Math.PI*Math.min(1,t*1.6))*Math.pow(1-t,1.5)*(.55+.45*Math.random())}
  const src=actx.createBufferSource(),bp=actx.createBiquadFilter(),g=actx.createGain();
  src.buffer=buf;bp.type='bandpass';bp.frequency.value=2200;bp.Q.value=.7;g.gain.value=.22;
  src.connect(bp).connect(g).connect(actx.destination);src.start();
 }catch(_){}
}
const $=id=>document.getElementById(id),ind=$('ind'),back=$('back'),fwd=$('fwd'),startB=$('start'),coverB=$('cover');
function visible(){const L=pf.getCurrentPageIndex();if(SINGLE||L===0||L===N-1)return [L];const a=L%2?L:L-1;return [a,a+1]}
const FRONT=()=>readToLib(0),BACKC=()=>readToLib(N-1);
function update(){
 const L=pf.getCurrentPageIndex(),front=L===FRONT(),backC=L===BACKC();
 stage.classList.toggle('open',!SINGLE&&!front&&!backC);stage.classList.toggle('single',SINGLE);
 // a closed cover shows on one half of the book area: centre it
 const half=L===0?'translateX(-25%)':'translateX(25%)';
 stage.style.transform=!SINGLE&&(front||backC)?half:'none';
 let t;if(front)t='الغلاف';else if(backC)t='الغلاف الخلفي';
 else t=`الصفحة ${toAr(Math.min(...visible().map(libToRead)))} من ${toAr(N-2)}`;
 ind.textContent=t;back.disabled=front;fwd.disabled=backC;
 startB.classList.toggle('hide',!front);coverB.classList.toggle('hide',front);
 const r=libToRead(L);$('hint').textContent=front?'اضغط «هيا نقرأ القصة» لفتح الكتاب من جهة اليمين':
  (innerWidth<innerHeight&&innerWidth<700?'أدِر الهاتف أفقيًا ليكبر الكتاب':(r<=4?'لتقليب الصفحة: اضغط على الصفحة اليسرى أو اسحبها نحو اليمين، كما في الكتاب العربي':''));
 const f=libToRead(L)/(N-1); // read pages pile up on the side they were turned to
 const readSide=AR_?'--rs':'--ls',restSide=AR_?'--ls':'--rs';
 stage.style.setProperty(readSide,(3+f*11).toFixed(1)+'px');stage.style.setProperty(restSide,(3+(1-f)*11).toFixed(1)+'px');
 document.querySelectorAll('.page.show').forEach(e=>e.classList.remove('show'));
 const pages=bookEl.querySelectorAll('.page');visible().forEach(i=>{const e=pages[i];if(e){void e.offsetWidth;e.classList.add('show')}});
}
let lockUntil=0; // ignore extra clicks while a page is still turning
const ready=()=>state!=='flipping'&&Date.now()>lockUntil;
let queued=null; // a click made while a page is turning waits for that turn to finish (at most one)
const go=fn=>{if(!ready()){queued=fn;return}lockUntil=Date.now()+300;fn()};
function runQueued(){if(queued&&state==='read'){const f=queued;queued=null;setTimeout(()=>go(f),60)}}
const next=()=>go(()=>AR_?pf.flipPrev('bottom'):pf.flipNext('bottom'));
const prev=()=>go(()=>AR_?pf.flipNext('bottom'):pf.flipPrev('bottom'));
const toCover=()=>go(()=>pf.flip(FRONT(),'bottom'));
function start(){
 fitText();
 const lib=Array.from({length:N},(_,L)=>els[libToRead(L)]);
 lib.forEach(e=>bookEl.appendChild(e));
 const want=+(location.hash.match(/p(\d+)/)||[0,0])[1];
 pf=new St.PageFlip(bookEl,{width:550,height:720,size:'stretch',minWidth:120,maxWidth:1400,minHeight:157,maxHeight:1830,
  showCover:true,usePortrait:SINGLE,mobileScrollSupport:false,maxShadowOpacity:.75,flippingTime:1100,drawShadow:true,showPageCorners:true,
  startPage:Math.min(Math.max(readToLib(want),0),N-1),clickEventForward:true});
 pf.loadFromHTML(bookEl.querySelectorAll('.page'));
 pf.on('flip',update);pf.on('changeOrientation',update);pf.on('init',update);
 pf.on('changeState',e=>{if(e.data==='flipping'&&state!=='flipping')rustle();state=e.data;if(state==='read')runQueued()});
 renderQuiz();
 setTimeout(()=>{update();stage.classList.add('ready')},60);
 fwd.onclick=next;back.onclick=prev;startB.onclick=next;coverB.onclick=toCover;
 bookEl.addEventListener('click',e=>{if(e.target.closest('[data-start]')){next();return}if(e.target.closest('[data-cover]')){toCover();return}onQuiz(e)});
 addEventListener('keydown',e=>{if(e.key==='ArrowLeft')next();if(e.key==='ArrowRight')prev()});
}
$('snd').onclick=()=>{soundOn=!soundOn;$('snd').textContent=soundOn?'🔊 الصوت':'🔈 بدون صوت'};
$('fs').onclick=()=>{try{document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen()}catch(_){}};
document.addEventListener('fullscreenchange',()=>{$('fs').textContent=document.fullscreenElement?'الخروج من ملء الشاشة':'ملء الشاشة';setTimeout(fit,100)});
if(!window.St){document.body.insertAdjacentHTML('beforeend','<p style="text-align:center">تعذّر تحميل الكتاب، يرجى تحديث الصفحة.</p>')}
else Promise.race([document.fonts?document.fonts.ready:Promise.resolve(),new Promise(r=>setTimeout(r,2500))]).then(start);
